{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C25"],
      "claim": "Valbenazine, a dimethoxytetrahydroisoquinoline derivative structurally similar to the query, has an absolute oral bioavailability of approximately 49% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Noscapine, a dimethoxy-substituted isoquinoline alkaloid, has an absolute oral bioavailability of 30% in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Verapamil, a dimethoxyphenyl basic amine related to the query, has an absolute oral bioavailability of 34% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C67"],
      "claim": "Sulpiride, a methoxybenzamide with a basic amine, has an oral bioavailability of 35% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Encainide, a methoxybenzamide antiarrhythmic, has an oral bioavailability of 32 ± 7% in normal subjects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C60"],
      "claim": "Levosulpiride, a close sulpiride analog, has an absolute oral bioavailability of 23.4% after oral administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C71"],
      "claim": "Verapamil bioavailability averaged 19.4% in 20 normal young men, slightly below the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F >= 20%) based on transferable evidence from structurally related dimethoxytetrahydroisoquinoline and methoxybenzamide analogs with oral bioavailability mostly 23-49%; the strongest structural analog valbenazine has F ~49%, and only a single borderline verapamil estimate falls below 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule itself.",
    "Uncertainty about whether the lactam and propylamine chain alter first-pass metabolism relative to valbenazine or verapamil.",
    "Verapamil data straddle the 20% threshold, introducing borderline uncertainty for that analog family."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

